   ["Constelação", "Norlatiadeque", "Edêntia", "O de número 70 no universo de Nébadon", "15:14.6"],
   ["Universo local", "Nébadon", "Sálvington", "O de número oitenta e quatro no setor menor de Ensa", "15:14.6"],
   ["Setor menor", "Ensa", "U Menor, a terceira", "O de número três no setor maior de Esplândon", "15:14.7"],
   ["Setor maior", "Esplândon", "U Maior, a quinta", "O quinto setor maior do superuniverso de Orvônton", "15:14.7"],
